// ===================== HJÁLPARFÖLL (notuð bæði við smíði og í síðunni) =====================
const R = {
  ri: (a, b) => a + Math.floor(Math.random() * (b - a + 1)),
  rs: (a, b, step) => { const n = Math.round((b - a) / step); return +(a + step * Math.floor(Math.random() * (n + 1))).toFixed(10); },
  pick: arr => arr[Math.floor(Math.random() * arr.length)],
  shuffle: arr => { const a = arr.slice(); for (let i = a.length - 1; i > 0; i--) { const j = Math.floor(Math.random() * (i + 1)); [a[i], a[j]] = [a[j], a[i]]; } return a; }
};

// Íslensk talnasnið: punktur skilur þúsundir, komma aukastafi.
const F = makeF({ pctDigits: 2 });

// Fjármálaföll. Vextir eru alltaf hlutföll (0,08), tími í árum.
const FIN = {
  fv: (pv, r, t) => pv * Math.pow(1 + r, t),
  pv: (fv, r, t) => fv / Math.pow(1 + r, t),
  fvifa: (r, t) => (Math.pow(1 + r, t) - 1) / r,
  pvifa: (r, t) => (1 - Math.pow(1 + r, -t)) / r,
  ear: (apr, m) => Math.pow(1 + apr / m, m) - 1,
  npv: (r, cfs) => cfs.reduce((s, c, t) => s + c / Math.pow(1 + r, t), 0),       // cfs[0] á tíma 0
  pvIn: (r, cfs) => cfs.reduce((s, c, t) => t ? s + c / Math.pow(1 + r, t) : s, 0),
  irr: cfs => { let lo = -0.99, hi = 5; const f = r => FIN.npv(r, cfs); let flo = f(lo);
    if (flo * f(hi) > 0) return NaN;
    for (let i = 0; i < 300; i++) { const mid = (lo + hi) / 2; const fm = f(mid); if (Math.abs(fm) < 1e-12) return mid; if (flo * fm < 0) hi = mid; else { lo = mid; flo = fm; } }
    return (lo + hi) / 2; },
  mirr: (cfs, r) => { const T = cfs.length - 1; let pvOut = 0, tv = 0;
    cfs.forEach((c, t) => { if (c < 0) pvOut += -c / Math.pow(1 + r, t); else tv += c * Math.pow(1 + r, T - t); });
    return Math.pow(tv / pvOut, 1 / T) - 1; },
  pi: (r, cfs) => FIN.pvIn(r, cfs) / -cfs[0],
  payback: cfs => { let cum = cfs[0]; for (let t = 1; t < cfs.length; t++) { if (cum + cfs[t] >= 0) return t - 1 + (-cum) / cfs[t]; cum += cfs[t]; } return Infinity; },
  // Skuldabréf: greiðslur á tímum times (í árum), coupon c á hverja greiðslu, nafnverð greitt með síðustu greiðslu.
  bondT: (c, par, r, times) => times.reduce((s, t, i) => s + (c + (i === times.length - 1 ? par : 0)) / Math.pow(1 + r, t), 0),
  bondISL: (cAnnual, par, r, years, m = 1) => { const ts = []; for (let k = 1; k <= years * m; k++) ts.push(k / m); return FIN.bondT(cAnnual / m, par, r, ts); },
  bondUS: (cAnnual, par, r, years, m = 1) => { const n = years * m, i = r / m, c = cAnnual / m; return c * FIN.pvifa(i, n) + par / Math.pow(1 + i, n); },
  gordon: (D1, r, g) => D1 / (r - g),
  ytmApprox: (c, par, P, n) => (c + (par - P) / n) / ((par + P) / 2),
  mean: a => a.reduce((s, x) => s + x, 0) / a.length,
  sdS: a => { const m = FIN.mean(a); return Math.sqrt(a.reduce((s, x) => s + (x - m) ** 2, 0) / (a.length - 1)); },
  covS: (a, b) => { const ma = FIN.mean(a), mb = FIN.mean(b); return a.reduce((s, x, i) => s + (x - ma) * (b[i] - mb), 0) / (a.length - 1); },
  corr: (a, b) => FIN.covS(a, b) / (FIN.sdS(a) * FIN.sdS(b))
};

// Útreikningur í línum með jöfnumerkjum í dálkum. calc('a = b = c', '', 'd = e')
function calc(...rows) {
  return '<div class="f"><table class="cl">' + rows.map(r => r === '' ? '<tr class="sp"><td></td></tr>'
    : '<tr>' + String(r).split(' = ').map((c, i) => (i ? '<td class="eq">=</td>' : '') + `<td>${c}</td>`).join('') + '</tr>').join('') + '</table></div>';
}
const trap = html => `<p class="trap"><b>Gildra.</b> ${html}</p>`;
const note = html => `<p class="note">${html}</p>`;
const traps = list => '<ul class="traps">' + list.map(([v, why]) => `<li><b>${v}</b> ${why}</li>`).join('') + '</ul>';
const tbl = (head, rows, cls = 'dt') => `<table class="${cls}"><thead><tr>${head.map(h => `<th>${h}</th>`).join('')}</tr></thead><tbody>${rows.map(r => `<tr>${r.map(c => `<td>${c}</td>`).join('')}</tr>`).join('')}</tbody></table>`;

// Byggir 5 ólíka valkosti; rétta svarið fremst (a = 0). Stokkað þegar spurningin birtist.
function opts(correct, distract, fmt, perturb) {
  const c = fmt(correct); const out = [c]; const seen = new Set([c]);
  for (const d of distract) { if (d === null || d === undefined || (typeof d === 'number' && !isFinite(d))) continue; const s = typeof d === 'string' ? d : fmt(d); if (!seen.has(s)) { seen.add(s); out.push(s); } if (out.length === 5) break; }
  let k = 1;
  while (out.length < 5 && k < 200) { const v = perturb(correct, k); const s = fmt(v); if (!seen.has(s)) { seen.add(s); out.push(s); } k++; }
  return out;
}
const pertAdd = step => (c, k) => c + (k % 2 ? 1 : -1) * Math.ceil(k / 2) * step;
const pertMul = f => (c, k) => c * (1 + (k % 2 ? 1 : -1) * Math.ceil(k / 2) * f);

// Fyrstu 5 ólíku strengirnir; rétt svar er fremst.
function uniq5(list) { const out = []; for (const x of list) { if (!out.includes(x)) out.push(x); if (out.length === 5) break; } let k = 2; while (out.length < 5) out.push(out[0] + ' (' + k++ + ')'); return out; }

// Les tölusvar: „1.138.889", „9,82", „9,82%", „−3,5", „1 200". Skilar NaN ef ólæsilegt.
function parseNum(s) {
  if (s === null || s === undefined) return NaN;
  let t = String(s).trim().replace(/[\s ]/g, '').replace(/[−–]/g, '-').replace(/kr\.?|%|\$|ár|dalir|dali/gi, '');
  if (!t) return NaN;
  if (t.includes(',')) { t = t.replace(/\./g, '').replace(',', '.'); }
  else if (/^-?\d{1,3}(\.\d{3})+$/.test(t)) { t = t.replace(/\./g, ''); }
  if (!/^-?\d*\.?\d+$/.test(t)) return NaN;
  return parseFloat(t);
}


