// Formúlur eftir fyrirlestrum (lykill = id úr LECTURES). Til að bæta F10 við: bættu við lykli hér.
const SHEET_LEC = {
  F1: `<ul><li>Sex lögmál: tímavirði · áhætta krefst ávöxtunar · dreifing · skilvirkir markaðir · umboðsvandi · orðspor</li><li>Fjórir þættir kerfisins: löggjöf og eftirlit · peningakerfið · fjármálastofnanir · fjármálamarkaðir</li></ul>
    ${calc('E(X) = Σ p<sub>i</sub> x<sub>i</sub>', 'Jafnvægislíkur: (1 − p) × x<sub>góð</sub> = E(B)')}`,
  F2: calc('Eiginfjárhlutfall = (virði − lán) / virði', 'LTV = lán / virði · hámarksfall = 1 − LTV', 'Endurheimt = það sem kröfuhafi fær / krafa', 'R<sub>ISK</sub> = (1 + R<sub>USD</sub>) × S<sub>1</sub>/S<sub>0</sub> − 1') +
    `<ul><li>Kröfuröð (staðfest): veðtryggðir → óveðtryggðir (skuldabréf) → forgangshluthafar → almennir hluthafar</li><li>Repo og seðlabankafé: enginn eftirmarkaður</li></ul>`,
  F3: calc('r = RR + IP + DRP + MRP + LP', 'Ríkisvíxill: r = RR + IP · langt ríkisbréf: r = RR + IP + MRP', 'r<sub>fyrirtæki</sub> − r<sub>ríki</sub> (sami líftími) = DRP + LP', '(1 + i) = (1 + r)(1 + π)', 'r = (1 + i)/(1 + π) − 1 · π* = (1 + i)/(1 + r) − 1', 'IP markaðarins = RIKB − RIKS (frádráttur)', 'Flatir vextir: P × r × d/360', 'Common equity = EF / eignir · Tier 1 = (EF + TP − óefnisl.) / RWA ≥ 6% · Total ≥ 8%', 'Nýtt hlutafé: (E + X)/(A + X) = k'),
  F4: calc('FV = PV(1 + r)<sup>t</sup> · PV = FV/(1 + r)<sup>t</sup>', 'FV = PV(1 + r/m)<sup>t·m</sup> · EAR = (1 + r/m)<sup>m</sup> − 1', 'FVA = PMT[(1 + r)<sup>t</sup> − 1]/r · PVA = PMT[1 − (1 + r)<sup>−t</sup>]/r', 'FVAD = FVA(1 + r) · PVAD = PVA(1 + r)', 'r = (FV/PV)<sup>1/t</sup> − 1 · t = ln(FV/PV)/ln(1 + r)', 'Flatir: 1 + r·d/360 · ósamfelldir: (1 + r)<sup>d/360</sup> · samfelldir: e<sup>r·d/360</sup>', 'r<sub>s</sub> = m ln(1 + r<sub>ó</sub>/m) · r<sub>ó</sub> = e<sup>r<sub>s</sub></sup> − 1', 'EAR úr dögum = (Lok/Upphaf)<sup>360/d</sup> − 1'),
  F5: calc('P = Σ c/(1 + r)<sup>t</sup> + Par/(1 + r)<sup>n</sup>', 'ÍSL: hálfsárs greiðsla núvirt með (1 + r)<sup>0,5</sup>', 'US: r/m og n·m tímabil · EAY = (1 + r/m)<sup>m</sup> − 1', 'Áfallnir vextir = c × liðinn tími · Clean = Dirty − áfallnir', 'YTM ≈ [c + (Par − P)/n] / [(Par + P)/2]', 'P<sub>0</sub> = D/r (fastur) · P<sub>0</sub> = D<sub>1</sub>/(r − g) · r = D<sub>1</sub>/P<sub>0</sub> + g', 'P<sub>n</sub> = D<sub>n</sub>(1 + g<sub>2</sub>)/(r − g<sub>2</sub>), núvirt með (1 + r)<sup>n</sup>', 'R<sub>ár</sub> = (1 + R)<sup>1/T</sup> − 1', 'V/H = Mcap/hagnaður · V/I = Mcap/bókf. EF · A/V = arður/Mcap'),
  F6: calc('Margin = (verð × fjöldi − lán) / (verð × fjöldi)', 'Veðkall: P = Lán / [n(1 − viðhaldskrafa)]', 'Kaupréttur = max(S − K; 0) · söluréttur = max(K − S; 0)', 'Break-even: kaupr. K + verð · sölur. K − verð', 'Útgáfukostn. = gengismunur + beinn kostn.; undirverðlagning = (P<sub>1</sub> − P<sub>útb</sub>)/P<sub>útb</sub>') +
    `<ul><li>Hollenskt uppboð: raða frá hæsta verði; útboðsverð = hæsta verð sem kemur öllu magni út; allir greiða það</li><li>Market order kaupir á ask, selur á bid</li></ul>`,
  F7: calc('R<sub>t</sub> = (P<sub>t</sub> − P<sub>t−1</sub> + D<sub>t</sub>)/P<sub>t−1</sub>', 'R̄ = ΣR/T · s = √[Σ(R − R̄)²/(T − 1)] · CV = s/R̄', 'E(R) = Σ p<sub>i</sub> R<sub>i</sub> · σ² = Σ p<sub>i</sub>(R<sub>i</sub> − E(R))²', 'E(R<sub>p</sub>) = Σ w<sub>i</sub> E(R<sub>i</sub>) · β<sub>p</sub> = Σ w<sub>i</sub> β<sub>i</sub>', 'E(R<sub>i</sub>) = RFR + β<sub>i</sub>[E(R<sub>M</sub>) − RFR]', 'β = Cov(R<sub>i</sub>, R<sub>M</sub>)/σ²<sub>M</sub> = ρ σ<sub>i</sub>/σ<sub>M</sub>') +
    `<ul><li>Veik: tæknigreining virkar ekki · hálfsterk: hvorki tækni- né grunngreining (US) · sterk: ekkert (ekki til í raun)</li></ul>`,
  F9: calc('NPV = −C<sub>0</sub> + Σ CF<sub>t</sub>/(1 + r)<sup>t</sup>', '0 = −C<sub>0</sub> + Σ CF<sub>t</sub>/(1 + IRR)<sup>t</sup>', 'PI = Σ CF<sub>t</sub>/(1 + r)<sup>t</sup> / C<sub>0</sub>', 'TV = Σ CIF<sub>t</sub>(1 + r)<sup>T−t</sup> · MIRR = (TV/PV<sub>útfl.</sub>)<sup>1/T</sup> − 1', 'IRR 2 ára: −C x² + a x + b = 0, x = 1 + IRR'),
  F10: calc('WACC = w<sub>d</sub>k<sub>d</sub> + w<sub>e</sub>k<sub>e</sub>', 'w<sub>d</sub> = D / (D + E), markaðsvirði · w<sub>e</sub> = 1 − w<sub>d</sub>', 'k<sub>d</sub> = YTM × (1 − T)', 'k<sub>e</sub> = RFR + β<sub>G</sub> × ERP', 'β<sub>G</sub> = β<sub>Ó</sub>[1 + (D/E)(1 − T)]', 'β<sub>Ó</sub> = β<sub>G</sub> / [1 + (D/E)(1 − T)]', 'Skattaskjöldur = vextir × T') +
    `<ul><li>Nýtt skuldahlutfall: (1) aflétta við gamla D/E, (2) gíra upp við nýja D/E</li><li>WACC sem fall af gírun er U-laga; lágmarkið er kjörfjármagnsskipan</li><li>Óráðstafað eigið fé kostar k<sub>e</sub> (fórnarkostnaður)</li><li>Meðaláhættusamt verkefni: WACC fyrirtækisins, óháð því hvernig verkefnið er fjármagnað · áhættumeira verkefni: hærri krafa</li></ul>`
};

